{"path":"about.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>About • {{BUSINESS_NAME}}</title>
  <style>
    :root{--glass-bg:rgba(255,255,255,0.08);--glass-border:rgba(255,255,255,0.12);--accent:#6b5dd3;--muted:#cfcfe8;--glass-radius:14px}
    html,body{height:100%;margin:0;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue';background:#0f1020;color:#eaeaf6}
    .site{min-height:100%;display:flex;flex-direction:column}
    header{backdrop-filter: blur(8px);background:linear-gradient(180deg, rgba(255,255,255,0.02), transparent);padding:18px;border-bottom:1px solid var(--glass-border)}
    nav{display:flex;gap:18px;align-items:center;justify-content:space-between;max-width:1100px;margin:0 auto}
    .brand{font-weight:700;color:var(--accent)}
    .navlinks{display:flex;gap:12px;align-items:center}
    .navlinks a{color:var(--muted);text-decoration:none;padding:8px 12px;border-radius:10px}
    .navlinks a:hover{background:var(--glass-bg);color:#fff}
    .container{max-width:1100px;margin:36px auto;padding:20px}
    .hero{display:grid;grid-template-columns:1fr 360px;gap:28px;align-items:start}
    .card{background:linear-gradient(135deg, rgba(255,255,255,0.03), rgba(255,255,255,0.01));border-radius:var(--glass-radius);padding:22px;border:1px solid var(--glass-border);box-shadow:0 8px 30px rgba(10,10,20,0.5)}
    h1{margin:0 0 8px 0;font-size:30px}
    p.lead{color:var(--muted);margin:0 0 16px}
    .cta{display:inline-block;background:var(--accent);color:white;padding:10px 14px;border-radius:10px;text-decoration:none;font-weight:600}
    .secondary{margin-left:10px;padding:10px 12px;border-radius:10px;background:transparent;border:1px solid var(--glass-border);color:var(--muted);text-decoration:none}

    /* Pattern */
    .bg-svg{position:fixed;inset:0;z-index:-1;opacity:0.12}
    /* Proof gallery */
    .proof{display:flex;flex-direction:column;gap:12px}
    .testimonial{min-height:88px;display:flex;gap:12px;align-items:flex-start}
    .quote{font-style:italic;color:#fff}
    .by{color:var(--muted);font-size:13px}
    .badges{display:flex;gap:8px;align-items:center}
    .badge{background:rgba(255,255,255,0.04);padding:6px 8px;border-radius:8px;border:1px solid var(--glass-border);position:relative}
    .badge[data-tip]:hover::after{content:attr(data-tip);position:absolute;left:50%;transform:translateX(-50%);bottom:calc(100% + 8px);background:#111;color:#fff;padding:8px;border-radius:6px;white-space:nowrap;font-size:12px}
    .controls{display:flex;gap:8px;margin-top:6px}
    .dot{width:10px;height:10px;border-radius:50%;background:rgba(255,255,255,0.06)}
    .dot.active{background:var(--accent)}

    footer{padding:20px;border-top:1px solid var(--glass-border);color:var(--muted);text-align:center;margin-top:40px}
    .note{font-size:13px;color:var(--muted);margin-top:14px}
    @media(max-width:900px){.hero{grid-template-columns:1fr;}.navlinks{display:none}}
  </style>
</head>
<body>
  <svg class='bg-svg' width='100%' height='100%' xmlns='http://www.w3.org/2000/svg' preserveAspectRatio='none'>
    <defs>
      <linearGradient id='g1' x1='0' x2='1'>
        <stop offset='0' stop-color='#6b5dd3'/>
        <stop offset='1' stop-color='#00c2a8'/>
      </linearGradient>
      <pattern id='p1' width='120' height='120' patternUnits='userSpaceOnUse' patternTransform='rotate(15)'>
        <rect width='120' height='120' fill='none'/>
        <circle cx='10' cy='10' r='3' fill='url(#g1)' opacity='0.18'/>
        <path d='M0 60 L120 60' stroke='url(#g1)' stroke-width='0.7' opacity='0.06'/>
      </pattern>
    </defs>
    <rect width='100%' height='100%' fill='url(#p1)'/>
  </svg>
  <div class='site'>
    <header>
      <nav>
        <div class='brand'>{{BUSINESS_NAME}}</div>
        <div class='navlinks'>
          <a href='index.html'>Welcome</a>
          <a href='about.html' aria-current='page'>Who I Am</a>
          <a href='specialties.html'>Focus Areas</a>
          <a href='approach.html'>How I Work</a>
          <a href='fees.html'>Investment</a>
          <a href='faq.html'>Q&amp;A</a>
          <a href='book.html'>Reserve</a>
          <a href='contact.html'>Say Hello</a>
        </div>
      </nav>
    </header>

    <main class='container'>
      <div class='hero'>
        <section class='card'>
          <h1>Calm perspective for the parts of life that feel messy</h1>
          <p class='lead'>I work with adults wanting clearer thinking, steadier routines, and kinder relationships with themselves. We focus on practical shifts you can keep—no quick fixes, just steady work together.</p>
          <a class='cta' href='{{PRIMARY_CTA_URL}}'>{{PRIMARY_CTA_LABEL}}</a>
          <a class='secondary' href='book.html'>See session options</a>

          <div style='margin-top:18px'>
            <strong style='display:block;margin-bottom:6px'>A note from me</strong>
            <p style='margin:0;color:var(--muted);font-size:14px'>I aim to offer clear clinical perspective while honoring your pace. Therapy here prioritizes collaborative exploration and measurable steps you can try between sessions. Sessions are confidential within professional and legal limits; they do not replace emergency services. If you are in crisis or feel unsafe, please call local emergency services or your crisis line immediately.</p>
          </div>
        </section>

        <aside class='card'>
          <div style='display:flex;justify-content:space-between;align-items:center;margin-bottom:10px'>
            <div style='font-weight:700'>Proof Gallery</div>
            <div style='font-size:13px;color:var(--muted)'>Real notes, names withheld</div>
          </div>

          <div class='proof' id='proof'>
            <div id='testimonial' class='testimonial'>
              <div style='width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,#6b5dd3,#00c2a8);display:flex;align-items:center;justify-content:center;font-weight:700'>S</div>
              <div>
                <div class='quote' id='quote'>"Working together helped me untangle a complicated work boundary without losing my sense of self."</div>
                <div class='by' id='by'>— person in their 30s</div>
              </div>
            </div>

            <div style='display:flex;justify-content:space-between;align-items:center;margin-top:10px'>
              <div class='badges' aria-hidden='false'>
                <div class='badge' data-tip='Licensed clinician, state board'>LIC</div>
                <div class='badge' data-tip='20+ hours/yr of continued education'>CE</div>
                <div class='badge' data-tip='Collaborates with local care teams'>Co-op</div>
              </div>
              <div class='controls' id='dots'></div>
            </div>

          </div>
        </aside>
      </div>

      <section style='margin-top:24px' class='card'>
        <h2 style='margin-top:0'>Therapeutic scope & boundaries</h2>
        <p style='color:var(--muted)'>I primarily support adults with anxiety, life transitions, relationship shifts, and work stress. I do not provide medication management or forensic evaluations. I will collaborate with prescribers, primary care clinicians, or other supports where appropriate.</p>

        <div style='margin-top:12px;display:flex;gap:12px'>
          <a class='cta' href='{{PRIMARY_CTA_URL}}'>Start a conversation</a>
          <a class='secondary' href='contact.html'>Questions first</a>
        </div>

        <p class='note'>Confidentiality is held within professional limits, including mandated reporting and imminent safety concerns. If you are experiencing an emergency, call local emergency services or {{PHONE}} if appropriate.</p>
      </section>

    </main>

    <footer>
      <div>{{BUSINESS_NAME}} • {{CITY}}, {{STATE}} • <a href='tel:{{PHONE}}' style='color:var(--muted);text-decoration:none'>Call</a> • <a href='mailto:{{EMAIL}}' style='color:var(--muted);text-decoration:none'>Email</a></div>
    </footer>
  </div>

  <script>
    (function(){
      const testimonials = [
        {q:'"Working together helped me untangle a complicated work boundary without losing my sense of self."', by:'— person in their 30s'},
        {q:'"I learned simple, daily practices that actually stuck and helped me sleep better."', by:'— parent adjusting to a new routine'},
        {q:'"The sessions felt grounded and practical; I could try small experiments between visits."', by:'— early career professional'},
        {q:'"We mapped out how to ask for support without losing autonomy. That was huge."', by:'— client navigating a breakup'}
      ];
      let i=0; const quoteEl=document.getElementById('quote'); const byEl=document.getElementById('by');
      const dots=document.getElementById('dots');
      testimonials.forEach((t,idx)=>{const d=document.createElement('div');d.className='dot'+(idx===0?' active':'');d.title='View testimonial';d.addEventListener('click',()=>{show(idx)});dots.appendChild(d)});
      let interval = setInterval(()=>{i=(i+1)%testimonials.length;show(i)},4500);
      function show(idx){i=idx;quoteEl.textContent=testimonials[i].q;byEl.textContent=testimonials[i].by;Array.from(dots.children).forEach((d,di)=>d.className='dot'+(di===i?' active':''))}
      document.getElementById('proof').addEventListener('mouseenter',()=>clearInterval(interval));
      document.getElementById('proof').addEventListener('mouseleave',()=>interval=setInterval(()=>{i=(i+1)%testimonials.length;show(i)},4500));
    })();
  </script>
</body>
</html>"} 
{"path":"specialties.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>Focus Areas & Pricing • {{BUSINESS_NAME}}</title>
  <style>
    :root{--glass:rgba(255,255,255,0.06);--accent:#ff7aa2;--muted:#d9cfe1}
    body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto;background:#071022;color:#fff}
    header{padding:18px;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid rgba(255,255,255,0.04)}
    .nav a{color:var(--muted);text-decoration:none;margin-left:12px}
    main{max-width:1100px;margin:28px auto;padding:20px}
    .grid{display:grid;grid-template-columns:1fr 360px;gap:22px}
    .panel{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:18px;border-radius:12px;border:1px solid rgba(255,255,255,0.06)}
    h1{margin:0 0 6px 0}
    .switch{display:flex;align-items:center;gap:10px;margin-bottom:12px}
    .toggle{background:rgba(255,255,255,0.03);padding:6px;border-radius:999px;border:1px solid rgba(255,255,255,0.06);display:inline-flex}
    .toggle button{border:0;background:transparent;padding:8px 14px;border-radius:999px;color:var(--muted);cursor:pointer}
    .toggle button.active{background:var(--accent);color:#0b0720;font-weight:700}
    .plans{display:flex;flex-direction:column;gap:12px}
    .plan{display:flex;justify-content:space-between;align-items:center;padding:12px;border-radius:10px;background:rgba(0,0,0,0.12)}
    .price{font-weight:800;font-size:20px;color:var(--accent)}
    .desc{color:var(--muted)}
    ul.specialties{margin:12px 0 0 16px;color:var(--muted)}
    .cta{display:inline-block;margin-top:12px;padding:10px 14px;border-radius:10px;background:var(--accent);color:#fff;text-decoration:none}
    /* small screens */
    @media(max-width:900px){.grid{grid-template-columns:1fr}.nav{display:none}}
  </style>
</head>
<body>
  <header>
    <div style='font-weight:700'>{{BUSINESS_NAME}}</div>
    <nav class='nav'>
      <a href='index.html'>Home</a>
      <a href='about.html'>About</a>
      <a href='specialties.html'>Focus Areas</a>
      <a href='contact.html'>Contact</a>
    </nav>
  </header>

  <main>
    <div class='grid'>
      <section class='panel'>
        <h1>Where I often join people</h1>
        <p class='desc'>I support adults navigating work strain, relationship shifts, caregiving changes, and the fog that comes with big life pivots. Below are common threads I help untangle with practical, evidence-informed approaches.</p>

        <ul class='specialties'>
          <li>Work overwhelm & burnout recovery</li>
          <li>Transitions: moves, career shifts, parenting changes</li>
          <li>Anxiety and worry that interferes with daily life</li>
          <li>Relationship patterns and communication skill-building</li>
        </ul>

        <a class='cta' href='{{PRIMARY_CTA_URL}}'>Join a cohort conversation</a>
      </section>

      <aside class='panel'>
        <div style='display:flex;justify-content:space-between;align-items:center;margin-bottom:8px'>
          <div style='font-weight:700'>Pricing comparator</div>
          <div style='font-size:13px;color:var(--muted)'>Toggle to compare</div>
        </div>

        <div class='switch'>
          <div style='font-size:13px;color:var(--muted)'>Monthly</div>
          <div class='toggle' role='tablist' aria-label='pricing toggle'>
            <button id='opt-monthly' class='active' aria-pressed='true'>Monthly</button>
            <button id='opt-package' aria-pressed='false'>Package</button>
          </div>
          <div style='font-size:13px;color:var(--muted)'>Package</div>
        </div>

        <div class='plans' id='plans'>
          <div class='plan'>
            <div>
              <div style='font-weight:700'>Momentum Monthly</div>
              <div class='desc'>Weekly sessions with short check-ins</div>
            </div>
            <div class='price' data-month='180' data-package='950'>$180</div>
          </div>

          <div class='plan'>
            <div>
              <div style='font-weight:700'>Clarity Package</div>
              <div class='desc'>Six-session focus on a specific goal</div>
            </div>
            <div class='price' data-month='220' data-package='1200'>$220</div>
          </div>

          <div class='plan'>
            <div>
              <div style='font-weight:700'>Drop-in Essentials</div>
              <div class='desc'>Flexible, single sessions for targeted work</div>
            </div>
            <div class='price' data-month='95' data-package='95'>$95</div>
          </div>
        </div>

        <div style='margin-top:12px;color:var(--muted);font-size:13px'>Prices shown for comparison. Packages include a short planning call and printable takeaways. Insurance not billed here; I can provide receipts for out-of-network reimbursement.</div>

      </aside>

    </div>

    <section style='margin-top:20px' class='panel'>
      <h2 style='margin-top:0'>How a cohort offering works</h2>
      <p class='desc'>I run time-limited cohorts with a small group size to practice skills, try experiments, and gain accountability—paired with optional individual check-ins. Cohorts are framed as collaborative learning rather than therapy alone; individual clinical needs may require private sessions.</p>
      <div style='margin-top:12px'><a class='cta' href='book.html'>See upcoming cohort dates</a></div>
    </section>

    <section style='margin-top:14px' class='panel'>
      <h3 style='margin-top:0'>Scope & accessibility</h3>
      <p class='desc'>I cannot provide emergency services or medication management. If you need urgent support, call local emergency services. My practice strives to be accessible; sliding scale spots may be available for cohort seats.</p>
    </section>

  </main>

  <script>
    (function(){
      const btnMonthly=document.getElementById('opt-monthly');
      const btnPackage=document.getElementById('opt-package');
      const prices=document.querySelectorAll('.price');
      function setMode(mode){
        btnMonthly.classList.toggle('active', mode==='month');
        btnPackage.classList.toggle('active', mode==='package');
        btnMonthly.setAttribute('aria-pressed', mode==='month');
        btnPackage.setAttribute('aria-pressed', mode==='package');
        prices.forEach(el=>{
          const target = mode==='month' ? el.getAttribute('data-month') : el.getAttribute('data-package');
          animateNumber(el, Number(target));
        })
      }
      function animateNumber(el,to){
        const from = Number(el.textContent.replace(/[^0-9\.]/g,''))||0;
        const duration=550; const start=performance.now();
        requestAnimationFrame(function raf(now){
          const t=Math.min(1,(now-start)/duration);
          const val = Math.round(from + (to-from)*easeOutCubic(t));
          el.textContent = '$'+val;
          if(t<1) requestAnimationFrame(raf);
        })
      }
      function easeOutCubic(t){return 1-Math.pow(1-t,3)}
      btnMonthly.addEventListener('click',()=>setMode('month'));
      btnPackage.addEventListener('click',()=>setMode('package'));
      // init monthly
      setMode('month');
    })();
  </script>
</body>
</html>"} 
{"path":"approach.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>How I Work • {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#061622;--glass:rgba(255,255,255,0.04);--accent:#2dd4bf;--muted:#bcded8}
    body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto;background:var(--bg);color:#e8fff7}
    header{padding:18px;border-bottom:1px solid rgba(255,255,255,0.03);display:flex;justify-content:space-between}
    main{max-width:1100px;margin:30px auto;padding:18px}
    .stack{display:grid;grid-template-columns:1fr 360px;gap:20px}
    .card{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:18px;border-radius:12px;border:1px solid rgba(255,255,255,0.06)}
    h1{margin:0 0 6px}
    .steps{display:flex;flex-direction:column;gap:12px;margin-top:10px}
    .step{display:flex;gap:12px;align-items:flex-start}
    .num{width:36px;height:36px;border-radius:9px;background:var(--glass);display:flex;align-items:center;justify-content:center;color:var(--muted);font-weight:700}
    .explain{color:var(--muted)}
    .cta{display:inline-block;margin-top:12px;padding:10px 14px;border-radius:10px;background:var(--accent);color:#012;text-decoration:none;font-weight:700}
    /* small */
    @media(max-width:900px){.stack{grid-template-columns:1fr}.nav{display:none}}
  </style>
</head>
<body>
  <header>
    <div style='font-weight:700'>{{BUSINESS_NAME}}</div>
    <nav class='nav'>
      <a href='index.html' style='color:var(--muted);text-decoration:none;margin-left:10px'>Home</a>
      <a href='about.html' style='color:var(--muted);text-decoration:none;margin-left:10px'>About</a>
      <a href='specialties.html' style='color:var(--muted);text-decoration:none;margin-left:10px'>Focus Areas</a>
    </nav>
  </header>

  <main>
    <div class='stack'>
      <section class='card'>
        <h1>My approach: compass, experiments, and steady pacing</h1>
        <p class='explain'>Think of therapy as a short series of experiments guided by a clinical compass. We name a direction, try an experiment, review, and revise. This keeps work concrete and humane.</p>

        <div class='steps'>
          <div class='step'>
            <div class='num'>1</div>
            <div>
              <div style='font-weight:700'>Map what's most important</div>
              <div class='explain'>We clarify what truly matters to you and set achievable, observable aims rather than vague goals.</div>
            </div>
          </div>

          <div class='step'>
            <div class='num'>2</div>
            <div>
              <div style='font-weight:700'>Try small experiments</div>
              <div class='explain'>Practical tasks you can do between sessions—short, measurable, reversible—so learning happens without overwhelm.</div>
            </div>
          </div>

          <div class='step'>
            <div class='num'>3</div>
            <div>
              <div style='font-weight:700'>Reflect & adjust</div>
              <div class='explain'>We track the results together and adapt based on what helps, not what we hope will work.</div>
            </div>
          </div>
        </div>

        <a class='cta' href='{{PRIMARY_CTA_URL}}'>Reserve a first slot</a>

        <p style='margin-top:12px;color:var(--muted);font-size:13px'>Sessions are private within legal limits. For urgent safety concerns, contact local emergency services. If you have specific clinical needs (e.g., medication management), I will coordinate care with your prescriber.</p>
      </section>

      <aside class='card'>
        <h3 style='margin-top:0'>Quick price view</h3>
        <p class='explain'>Animated toggle so you can quickly compare single session vs short package pricing.</p>

        <div style='display:flex;gap:8px;margin-bottom:12px'>
          <button id='single' style='padding:8px;border-radius:8px;border:1px solid rgba(255,255,255,0.04);background:var(--glass);color:var(--muted)'>Single</button>
          <button id='short' style='padding:8px;border-radius:8px;border:1px solid rgba(255,255,255,0.04);background:transparent;color:var(--muted)'>3-Session</button>
        </div>

        <div style='display:flex;flex-direction:column;gap:10px'>
          <div style='display:flex;justify-content:space-between;align-items:center'>
            <div>Intro Session</div>
            <div class='price' data-single='120' data-pack='330'>$120</div>
          </div>

          <div style='display:flex;justify-content:space-between;align-items:center'>
            <div>Focused Follow-up</div>
            <div class='price' data-single='95' data-pack='270'>$95</div>
          </div>
        </div>

        <div style='margin-top:12px;color:var(--muted);font-size:13px'>Packages blend planning and tools between sessions; no guarantees implied. If you are using insurance, I can provide receipts for reimbursement.</div>
      </aside>

    </div>

    <section style='margin-top:16px' class='card'>
      <h2 style='margin-top:0'>Clinical boundaries & what to expect</h2>
      <p class='explain'>I work from a relational, skills-oriented stance that integrates cognitive-behavioral tools, mindfulness, and real-world planning. Therapy here is collaborative: we set shared aims, check progress, and adjust together. I do not provide emergency services; for crisis, call local emergency lines.</p>
    </section>

  </main>

  <script>
    (function(){
      // Pricing toggle similar but compact
      const btnSingle=document.getElementById('single');
      const btnShort=document.getElementById('short');
      const priceEls=document.querySelectorAll('.price');
      function set(mode){
        btnSingle.style.background = mode==='single' ? 'var(--accent)' : 'transparent';
        btnSingle.style.color = mode==='single' ? '#021' : 'var(--muted)';
        btnShort.style.background = mode==='short' ? 'var(--accent)' : 'transparent';
        btnShort.style.color = mode==='short' ? '#021' : 'var(--muted)';
        priceEls.forEach(el=>{
          const target = mode==='single'?el.getAttribute('data-single'):el.getAttribute('data-pack');
          animate(el, Number(target));
        })
      }
      function animate(el,to){
        const from = Number(el.textContent.replace(/[^0-9\.]/g,''))||0; const dur=420; const s=performance.now();
        (function raf(n){const t=Math.min(1,(n-s)/dur);el.textContent='$'+Math.round(from + (to-from)*(1-Math.pow(1-t,3))); if(t<1)requestAnimationFrame(raf)})();
      }
      btnSingle.addEventListener('click',()=>set('single'));
      btnShort.addEventListener('click',()=>set('short'));
      set('single');
    })();
  </script>
</body>
</html>"} 
